frappe.ui.form.on('Purchase Order', {

    refresh(frm) {
        setup_columns(frm);
        const stale = (frm.doc.items || []).some(
            r => flt(r.custom_no_of_boxes) > 0 && flt(r.custom_total_pcs_row) === 0
        );
        stale ? recalc_all(frm) : update_po_totals(frm);
    },

    custom_factor(frm)       { recalc_all(frm); },
    custom_freight_rate(frm) { recalc_all(frm); },
});

frappe.ui.form.on('Purchase Order Item', {
    custom_no_of_boxes(frm, cdt, cdn)     { calc_and_refresh(frm, cdt, cdn); },
    custom_pcs_per_box(frm, cdt, cdn)     { calc_and_refresh(frm, cdt, cdn); },
    custom_price_rmb(frm, cdt, cdn)       { calc_and_refresh(frm, cdt, cdn); },
    custom_cbm_per_box(frm, cdt, cdn)     { calc_and_refresh(frm, cdt, cdn); },
    custom_projected_price(frm, cdt, cdn) { calc_and_refresh(frm, cdt, cdn); },
    items_remove(frm)                     { frm.refresh_field('items'); update_po_totals(frm); },
});

function setup_columns(frm) {
    frm.fields_dict.items.grid.set_column_disp([
        'item_code',
        'custom_no_of_boxes', 'custom_pcs_per_box', 'custom_total_pcs_row',
        'custom_price_rmb', 'custom_total_cost_rmb', 'custom_total_cost_kes',
        'custom_cost_per_item', 'custom_cbm_per_box', 'custom_total_cbm',
        'custom_total_freight', 'custom_freight_per_item', 'custom_unit_cost',
        'custom_projected_price', 'custom_proj_profit_unit', 'custom_total_proj_profit'
    ], true);

    frm.fields_dict.items.grid.set_column_disp([
        'schedule_date', 'uom', 'qty', 'rate', 'amount',
        'conversion_factor', 'stock_qty', 'price_list_rate',
        'discount_percentage', 'item_tax_template', 'warehouse',
        'net_rate', 'net_amount', 'is_free_item', 'apply_tds',
        'weight_per_unit', 'total_weight', 'expense_account',
        'cost_center', 'project', 'page_break'
    ], false);
}

// Pure calculation — mutates locals directly.
// Same pattern as ERPNext's calculate_item_values(): synchronous, no Promises, no events.
function calc(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    const factor     = flt(frm.doc.custom_factor);
    const frt        = flt(frm.doc.custom_freight_rate);
    const boxes      = flt(row.custom_no_of_boxes);
    const pcs_box    = flt(row.custom_pcs_per_box);
    const price_rmb  = flt(row.custom_price_rmb);
    const cbm_box    = flt(row.custom_cbm_per_box);
    const proj_price = flt(row.custom_projected_price);

    const total_pcs       = boxes * pcs_box;
    const total_rmb       = total_pcs * price_rmb;
    const total_kes       = total_rmb * factor;
    const total_cbm       = boxes * cbm_box;
    const total_freight   = total_cbm * frt;

    // Round each component first — matches Excel cell-by-cell behaviour.
    // profit and total_profit are then exact integers with no floating-point drift.
    const cost_per_item_r = total_pcs ? Math.round(total_kes / total_pcs) : 0;
    const freight_item_r  = total_pcs ? Math.round(total_freight / total_pcs) : 0;
    const unit_cost       = cost_per_item_r + freight_item_r;
    const profit_unit     = proj_price - unit_cost;
    const total_profit    = total_pcs * profit_unit;

    // Keep ERPNext's native qty in sync so its internal recalc doesn't clobber state.
    row.qty                      = total_pcs;
    row.custom_total_pcs_row     = total_pcs;
    row.custom_total_cost_rmb    = flt(total_rmb, 2);
    row.custom_total_cost_kes    = flt(total_kes, 0);
    row.custom_cost_per_item     = cost_per_item_r;
    row.custom_total_cbm         = flt(total_cbm, 3);
    row.custom_total_freight     = flt(total_freight, 0);
    row.custom_freight_per_item  = freight_item_r;
    row.custom_unit_cost         = unit_cost;
    row.custom_proj_profit_unit  = profit_unit;
    row.custom_total_proj_profit = total_profit;
}

// Single-row trigger: calc then refresh only this row, then header totals.
// Avoids full grid re-render which disrupts the user's active cell edit.
function calc_and_refresh(frm, cdt, cdn) {
    calc(frm, cdt, cdn);
    const grid_row = frm.fields_dict.items.grid.grid_rows_by_docname[cdn];
    if (grid_row) {
        grid_row.refresh();
    } else {
        frm.refresh_field('items');
    }
    update_po_totals(frm);
}

// Full recalc (factor or freight_rate changed): all rows then one grid repaint.
function recalc_all(frm) {
    (frm.doc.items || []).forEach(row => calc(frm, row.doctype, row.name));
    frm.refresh_field('items');
    update_po_totals(frm);
}

// PO header totals: direct assignment to frm.doc then refresh those fields.
function update_po_totals(frm) {
    let boxes = 0, pcs = 0, rmb = 0, kes = 0, cbm = 0, freight = 0, profit = 0;

    (frm.doc.items || []).forEach(r => {
        boxes   += flt(r.custom_no_of_boxes);
        pcs     += flt(r.custom_total_pcs_row);
        rmb     += flt(r.custom_total_cost_rmb);
        kes     += flt(r.custom_total_cost_kes);
        cbm     += flt(r.custom_total_cbm);
        freight += flt(r.custom_total_freight);
        profit  += flt(r.custom_total_proj_profit);
    });

    frm.doc.custom_total_boxes          = boxes;
    frm.doc.custom_total_pcs            = pcs;
    frm.doc.custom_total_cost_rmb_po    = flt(rmb, 2);
    frm.doc.custom_total_cost_kes_po    = flt(kes, 0);
    frm.doc.custom_total_cbm_po         = flt(cbm, 3);
    frm.doc.custom_total_freight_po     = flt(freight, 0);
    frm.doc.custom_total_proj_profit_po = flt(profit, 0);

    frm.refresh_fields([
        'custom_total_boxes', 'custom_total_pcs',
        'custom_total_cost_rmb_po', 'custom_total_cost_kes_po',
        'custom_total_cbm_po', 'custom_total_freight_po',
        'custom_total_proj_profit_po'
    ]);
}
